"use strict";(globalThis.webpackChunkdocs_site=globalThis.webpackChunkdocs_site||[]).push([[256],{7674(e){e.exports=JSON.parse('{"version":{"pluginId":"default","version":"current","label":"Next","banner":null,"badge":false,"noIndex":false,"className":"docs-version-current","isLast":true,"docsSidebars":{"docsSidebar":[{"type":"link","href":"/docs/","label":"Introduction","docId":"intro","unlisted":false},{"type":"category","label":"Getting Started","collapsed":false,"items":[{"type":"link","href":"/docs/getting-started/installation","label":"Installation","docId":"getting-started/installation","unlisted":false},{"type":"link","href":"/docs/getting-started/quickstart","label":"Quick Start","docId":"getting-started/quickstart","unlisted":false},{"type":"link","href":"/docs/getting-started/configuration","label":"Configuration","docId":"getting-started/configuration","unlisted":false}],"collapsible":true},{"type":"category","label":"Core Concepts","collapsed":false,"items":[{"type":"link","href":"/docs/concepts/causal-graph","label":"Causal Graph","docId":"concepts/causal-graph","unlisted":false},{"type":"link","href":"/docs/concepts/temporal-graph","label":"Temporal Graph","docId":"concepts/temporal-graph","unlisted":false},{"type":"link","href":"/docs/concepts/state-branching","label":"State Branching","docId":"concepts/state-branching","unlisted":false},{"type":"link","href":"/docs/concepts/vector-search","label":"Vector Search","docId":"concepts/vector-search","unlisted":false},{"type":"link","href":"/docs/concepts/reactive-state","label":"Reactive State","docId":"concepts/reactive-state","unlisted":false},{"type":"link","href":"/docs/concepts/lsm-tree","label":"LSM-Tree Storage","docId":"concepts/lsm-tree","unlisted":false}],"collapsible":true},{"type":"category","label":"Architecture","items":[{"type":"link","href":"/docs/architecture/overview","label":"Overview","docId":"architecture/overview","unlisted":false},{"type":"link","href":"/docs/architecture/gateway","label":"Gateway","docId":"architecture/gateway","unlisted":false},{"type":"link","href":"/docs/architecture/metadata-plane","label":"Metadata Plane","docId":"architecture/metadata-plane","unlisted":false},{"type":"link","href":"/docs/architecture/data-plane","label":"Data Plane","docId":"architecture/data-plane","unlisted":false},{"type":"link","href":"/docs/architecture/raft-consensus","label":"Raft Consensus","docId":"architecture/raft-consensus","unlisted":false}],"collapsed":true,"collapsible":true},{"type":"category","label":"API Reference","items":[{"type":"link","href":"/docs/api/agent-state-service","label":"AgentStateService","docId":"api/agent-state-service","unlisted":false},{"type":"link","href":"/docs/api/kv-operations","label":"KV Operations","docId":"api/kv-operations","unlisted":false},{"type":"link","href":"/docs/api/redis-protocol","label":"Redis Protocol","docId":"api/redis-protocol","unlisted":false}],"collapsed":true,"collapsible":true},{"type":"category","label":"SDKs","items":[{"type":"link","href":"/docs/sdks/python","label":"Python","docId":"sdks/python","unlisted":false},{"type":"link","href":"/docs/sdks/rust","label":"Rust","docId":"sdks/rust","unlisted":false},{"type":"link","href":"/docs/sdks/go","label":"Go","docId":"sdks/go","unlisted":false},{"type":"link","href":"/docs/sdks/java","label":"Java","docId":"sdks/java","unlisted":false},{"type":"link","href":"/docs/sdks/cpp","label":"C++","docId":"sdks/cpp","unlisted":false}],"collapsed":true,"collapsible":true},{"type":"category","label":"Deployment","items":[{"type":"link","href":"/docs/deployment/single-node","label":"Single Node","docId":"deployment/single-node","unlisted":false},{"type":"link","href":"/docs/deployment/docker","label":"Docker","docId":"deployment/docker","unlisted":false},{"type":"link","href":"/docs/deployment/kubernetes","label":"Kubernetes","docId":"deployment/kubernetes","unlisted":false}],"collapsed":true,"collapsible":true},{"type":"link","href":"/docs/benchmarks","label":"Benchmarks","docId":"benchmarks","unlisted":false}]},"docs":{"api/agent-state-service":{"id":"api/agent-state-service","title":"AgentStateService","description":"The AgentStateService is Statelet\'s core API for agent memory management. It provides unified access to causal graphs, temporal edges, state branching, reactive watches, and vector similarity search.","sidebar":"docsSidebar"},"api/kv-operations":{"id":"api/kv-operations","title":"KV Operations","description":"Statelet\'s distributed key-value API is accessible via gRPC (port 9379) or Redis protocol (port 6379).","sidebar":"docsSidebar"},"api/redis-protocol":{"id":"api/redis-protocol","title":"Redis Protocol","description":"Statelet natively supports the Redis RESP2 protocol on port 6379. Any existing Redis client can connect directly to Statelet without modification.","sidebar":"docsSidebar"},"architecture/data-plane":{"id":"architecture/data-plane","title":"Data Plane","description":"Each data node in the cluster runs a ShardEngine that manages its assigned shards. The data plane handles all read/write operations for key-value data, vector indexes, and agent state.","sidebar":"docsSidebar"},"architecture/gateway":{"id":"architecture/gateway","title":"Gateway","description":"The Gateway is Statelet\'s stateless routing layer. It accepts client connections and routes requests to the correct data node based on the shard map.","sidebar":"docsSidebar"},"architecture/metadata-plane":{"id":"architecture/metadata-plane","title":"Metadata Plane","description":"The Metadata Plane is a dedicated Raft consensus group that manages all cluster-wide state. It is separate from the data plane to avoid metadata operations contending with data operations.","sidebar":"docsSidebar"},"architecture/overview":{"id":"architecture/overview","title":"Overview","description":"Statelet uses a three-tier distributed architecture designed for horizontal scalability and fault tolerance.","sidebar":"docsSidebar"},"architecture/raft-consensus":{"id":"architecture/raft-consensus","title":"Raft Consensus","description":"Statelet uses the Raft consensus protocol for both metadata and data replication. The implementation uses a single-threaded event loop design for simplicity and correctness.","sidebar":"docsSidebar"},"benchmarks":{"id":"benchmarks","title":"Benchmarks","description":"Statelet\'s performance story is the unified engine: temporal graph, vector, and memory operations run inside the same process that stores the data, avoiding cross-service hops between a KV store, vector database, and graph database.","sidebar":"docsSidebar"},"concepts/causal-graph":{"id":"concepts/causal-graph","title":"Causal Graph","description":"The Causal Graph is Statelet\'s core primitive for recording AI agent reasoning. It models decision-making as a directed acyclic graph (DAG) where each node is a reasoning step and each edge captures a causal relationship.","sidebar":"docsSidebar"},"concepts/lsm-tree":{"id":"concepts/lsm-tree","title":"LSM-Tree Storage","description":"Statelet\'s storage engine is built on a Log-Structured Merge-Tree (LSM-Tree) architecture, optimized for high write throughput with competitive read performance.","sidebar":"docsSidebar"},"concepts/reactive-state":{"id":"concepts/reactive-state","title":"Reactive State","description":"Statelet provides compare-and-swap (CAS) operations for optimistic concurrency control and watch subscriptions for real-time state change notifications.","sidebar":"docsSidebar"},"concepts/state-branching":{"id":"concepts/state-branching","title":"State Branching","description":"Statelet provides lightweight fork/merge primitives with copy-on-write overlays. Agents can create branches to explore alternative reasoning paths without duplicating data or affecting the main timeline.","sidebar":"docsSidebar"},"concepts/temporal-graph":{"id":"concepts/temporal-graph","title":"Temporal Graph","description":"The Temporal Graph extends the Causal Graph with time-aware edges. Every edge carries a validity interval [validfrom, validto], enabling point-in-time queries, time-window traversals, and full edge version history.","sidebar":"docsSidebar"},"concepts/vector-search":{"id":"concepts/vector-search","title":"Vector Search","description":"Statelet includes a built-in HNSW (Hierarchical Navigable Small World) vector index for similarity search. Attach vector embeddings to reasoning steps, then find similar past reasoning chains across your agent\'s history.","sidebar":"docsSidebar"},"deployment/docker":{"id":"deployment/docker","title":"Docker","description":"Run Statelet as a multi-container cluster with Docker Compose.","sidebar":"docsSidebar"},"deployment/kubernetes":{"id":"deployment/kubernetes","title":"Kubernetes","description":"Production deployment with 3+ data nodes using StatefulSets for stable network identities and persistent storage.","sidebar":"docsSidebar"},"deployment/single-node":{"id":"deployment/single-node","title":"Single Node","description":"The local development topology runs all three Statelet services on one machine:","sidebar":"docsSidebar"},"getting-started/configuration":{"id":"getting-started/configuration","title":"Configuration","description":"Statelet can be configured via command-line arguments, configuration files, or environment variables.","sidebar":"docsSidebar"},"getting-started/installation":{"id":"getting-started/installation","title":"Installation","description":"Python (recommended)","sidebar":"docsSidebar"},"getting-started/quickstart":{"id":"getting-started/quickstart","title":"Quick Start","description":"This guide starts a local Statelet deployment and writes a key through the Python SDK.","sidebar":"docsSidebar"},"intro":{"id":"intro","title":"Introduction","description":"The agent runtime data layer for production AI systems.","sidebar":"docsSidebar"},"sdks/cpp":{"id":"sdks/cpp","title":"C++","description":"Official C++ client for Statelet. Requires C++17 or later.","sidebar":"docsSidebar"},"sdks/go":{"id":"sdks/go","title":"Go","description":"Official Go client for Statelet. Requires Go 1.21+.","sidebar":"docsSidebar"},"sdks/java":{"id":"sdks/java","title":"Java","description":"Official Java client for Statelet. Requires Java 17+.","sidebar":"docsSidebar"},"sdks/python":{"id":"sdks/python","title":"Python","description":"Official Python client for Statelet. Requires Python 3.9+.","sidebar":"docsSidebar"},"sdks/rust":{"id":"sdks/rust","title":"Rust","description":"Official Rust client for Statelet. Requires Rust 1.70+.","sidebar":"docsSidebar"}}}}')}}]);